/**
 * Turn the private quest extraction into the committed quest-browser index.
 *
 * The full extraction (handbook/facts/quests.json, regenerated by extract-quests.mjs) is large and contains the
 * quest pack's message text. The handbook does not publish copied dialogue, so this script keeps only the
 * facts a guide needs: names, givers, gates, generated locations, objectives/outcomes, clocks, rewards and the
 * source filename. Run it after extract-quests.mjs; the output is committed and the input stays local.
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../', import.meta.url));
const inputPath = process.env.QUEST_EXTRACTION || join(root, 'handbook/facts/quests.json');
const outputPath = join(root, 'handbook/quests/quests.json');
const full = JSON.parse(await readFile(inputPath, 'utf8'));

const categories = [
  { id: 'main', label: 'Main quest', blurb: 'The story of Lysandus, the Emperor\'s letter and the Totem of Tiber Septim.' },
  { id: 'questlines', label: 'Questlines', blurb: 'The 14 online lines introduced after character level 2, from the Court Crafter to the Dagon Cycle.' },
  { id: 'fighters', label: 'Fighters Guild', blurb: 'Hunts, escorts and guard work from the Fighters Guild halls.' },
  { id: 'mages', label: 'Mages Guild', blurb: 'Fetch work, field research and the occasional dangerous experiment for the Mages Guild.' },
  { id: 'thieves', label: 'Thieves Guild', blurb: 'The Guild\'s work in the General Populace pool: theft, smuggling, persuasion and quiet violence.' },
  { id: 'darkBrotherhood', label: 'Dark Brotherhood', blurb: 'Contracts, executions and the Brotherhood\'s own kind of discretion.' },
  { id: 'knightly', label: 'Knightly orders', blurb: 'Quests from the knightly orders: traitors, monsters, princes and the occasional dragonling.' },
  { id: 'temples', label: 'Temples', blurb: 'Exorcisms, relics, healings and heretics from the temples and templar orders.' },
  { id: 'nobles', label: 'Nobles', blurb: 'Deliveries, smuggling and discreet violence for the nobility of the Bay.' },
  { id: 'commoners', label: 'Commoners', blurb: 'The problems of ordinary people: lost children, strange beasts and local trouble.' },
  { id: 'merchants', label: 'Merchants and innkeepers', blurb: 'Trade, missing property and the practical work of the Bay\'s shopkeepers.' },
  { id: 'covens', label: 'Covens', blurb: 'Witch-coven errands: ingredients, escorts, exorcisms and the covens\' own feuds.' },
  { id: 'vampires', label: 'Vampire clans', blurb: 'The work a vampire is given by its bloodline: letters, rivals and the clan\'s enemies.' },
  { id: 'daedric', label: 'Daedric quests', blurb: 'A Prince of Oblivion asks for one thing, and usually means it.' },
  { id: 'cures', label: 'Cures', blurb: 'How a vampire or lycanthrope can be cured, when the hunter\'s letter arrives.' },
  { id: 'tutorial', label: 'Tutorial', blurb: 'The opening lesson in Privateer\'s Hold.' }
];
const categoryByGroup = new Map([
  ['FightersGuild', 'fighters'], ['MagesGuild', 'mages'], ['GeneralPopulace', 'thieves'],
  ['DarkBrotherHood', 'darkBrotherhood'], ['KnightlyOrder', 'knightly'], ['HolyOrder', 'temples'],
  ['Nobility', 'nobles'], ['Commoners', 'commoners'], ['Merchants', 'merchants'],
  ['Witches', 'covens'], ['Vampires', 'vampires'], ['Oblivion', 'daedric'],
  ['Cure', 'cures'], ['MainQuest', 'main'], ['Tutorial', 'tutorial'], ['Questline', 'questlines']
]);
const fallbackNames = {
  S0000100: "Akorithi's Minions", S0000101: "Wayrest's Assassins", S0000102: "Gortwog's Orcs",
  S0000103: "The King of Worms' Vampires", S0000104: "The Underking's Daedra",
  S0000106: "The King of Worms' Reward", S0000107: "Queen Aubk-i's Gratitude"
};
const guidePages = {
  _BRISIEN: 'reference/lady-brisienna/',
  '$CUREWER': 'reference/cures/',
  '$CUREVAM': 'reference/cures/',
  '_TUTOR__': 'reference/tutorial/'
};
const lineGuides = {
  introCrafts: 'reference/the-court-crafter/',
  introFirmament: 'reference/written-in-the-stars/',
  introBay: 'reference/the-bays-troubles/',
  burningDoors: 'reference/the-burning-doors/',
  covensHoard: 'reference/the-covens-hoard/',
  weirRoad: 'reference/the-weir-road/',
  hourThatWasNot: 'reference/the-hour-that-was-not/',
  oldCoil: 'reference/the-old-coil/',
  thirteenthFrostfall: 'reference/the-thirteenth-of-frostfall/',
  introGear: 'reference/the-smiths-secrets/',
  introSea: 'reference/the-harbormasters-word/',
  introRoad: 'reference/the-merchants-road/',
  introTables: 'reference/a-seat-at-the-table/',
  introArena: 'reference/the-heralds-call/'
};
const patternGuides = {
  fighters: 'reference/fighters-guild-hunts/',
  mages: 'reference/mages-guild-fetches/',
  temples: 'reference/temple-errands/',
  thieves: 'reference/thieves-guild-work/',
  darkBrotherhood: 'reference/dark-brotherhood-contracts/',
  knightly: 'reference/knightly-order-quests/',
  nobles: 'reference/noble-work/',
  commoners: 'reference/commoner-work/',
  merchants: 'reference/merchant-work/',
  covens: 'reference/coven-work/',
  vampires: 'reference/vampire-clan-work/',
  daedric: 'reference/daedric-quests/',
  cures: 'reference/cures/',
  tutorial: 'reference/tutorial/'
};
const mainOrder = id => id === '_BRISIEN' ? 0 : /^S0000(\d{3})/.test(id) ? Number(id.slice(5)) : 9999;
const lineOrder = new Map(full.questlines.map((l, i) => [l.id, i]));
const membership = { N: 'Non-member', M: 'Member', P: 'Prospect', T: 'Akatosh', A: 'Arkay', D: 'Dibella', J: 'Julianos', K: 'Kynareth', R: 'Mara', S: 'Stendarr', Z: 'Zenithar' };
const placeKind = raw => {
  if (/remote\s+dungeon/i.test(raw)) return 'remote dungeon';
  if (/remote\s+house/i.test(raw)) return 'remote house';
  if (/remote\s+town/i.test(raw)) return 'remote town';
  if (/permanent/i.test(raw)) return 'fixed place';
  if (/remote/i.test(raw)) return 'remote site';
  return raw.replace(/^[A-Za-z0-9_$.-]+\s+/, '').trim() || 'site';
};
const placeText = q => {
  const places = q.resources?.places ?? [];
  const kinds = [...new Set(places.map(p => placeKind(p.raw || '')))];
  return kinds.length ? kinds.join(', ') : 'not named until the quest starts';
};
const clockText = q => {
  const t = q.timeLimit;
  if (!t) return 'Varies';
  if (t.minDays == null && t.maxDays == null) return t.start === '0' && t.end === '0' ? 'None' : 'Varies';
  if ((t.minDays ?? 0) === 0 && (t.maxDays ?? 0) === 0) return 'None';
  const min = t.minDays ?? 0, max = t.maxDays ?? min;
  return min === max ? `${min} day${min === 1 ? '' : 's'}` : `${min}–${max} days`;
};
const requirementText = q => {
  const list = q.questList;
  if (!list) return q.group?.raw === 'MainQuest' ? 'Main story' : 'No list row';
  const bits = [];
  if (membership[list.membership]) bits.push(membership[list.membership]);
  if (list.minReq != null) bits.push(Number(list.minReq) >= 10 ? `reputation ${list.minReq}` : `rank/level ${list.minReq}`);
  if (list.flag === '1') bits.push('one-time');
  if (list.flag === 'X') bits.push('adult content');
  return bits.length ? bits.join(' · ') : 'None listed';
};
const cleanText = value => String(value ?? '')
  .replace(/_+([A-Za-z0-9.$]+)_+/g, (all, token) => {
    if (/dung|crypt|barrow|tower|castle/i.test(token)) return 'the named dungeon';
    if (/house|home/i.test(token)) return 'the named house';
    if (/tavern|inn|pit/i.test(token)) return 'the named tavern';
    if (/brother|prince|princess/i.test(token)) return 'the named royal';
    if (/monster|foe/i.test(token)) return 'the target';
    if (/reward/i.test(token)) return 'the reward';
    if (/qg|questgiver/i.test(token)) return 'the questor';
    return 'the named place';
  })
  .replace(/=[A-Za-z0-9.$]+_/g, 'the target')
  .replace(/%pcn/gi, 'you').replace(/%pcf/gi, 'you')
  .replace(/%g3/gi, 'their').replace(/%g2/gi, 'them').replace(/%g\b/gi, 'they').replace(/%reg/gi, 'the region')
  .replace(/the named ([a-z]+) in the named \1/gi, 'the named $1')
  .replace(/the named ([a-z]+) at the named \1/gi, 'the named $1');
const sheetSteps = q => Array.isArray(q.sheet?.objectives) ? q.sheet.objectives.map(o => ({ ...o, text: cleanText(o.text || o.id) })) : [];
const sheetOutcomes = q => Array.isArray(q.sheet?.outcomes) ? q.sheet.outcomes.map(o => ({ text: cleanText(o.text || o.id), pay: o.pay ?? null, failure: Boolean(o.failure) })) : [];
const kindOf = q => {
  if (q.group?.raw === 'MainQuest') return 'main';
  if (q.group?.raw === 'Questline') return 'questline';
  if (q.group?.raw === 'Tutorial') return 'tutorial';
  if (q.group?.raw === 'Cure') return 'cure';
  return 'generated';
};
const tagsOf = q => {
  const out = new Set();
  if (q.group?.raw === 'MainQuest') out.add('main-quest');
  if (q.group?.raw === 'Questline') out.add('questline');
  if (q.group?.raw === 'Oblivion') out.add('daedric');
  if (q.group?.raw === 'Cure') out.add('cure');
  if (q.resources?.foes?.length) out.add('combat');
  if (q.resources?.places?.some(p => /remote/i.test(p.raw))) out.add('generated-location');
  if (q.resources?.items?.some(i => !/gold|reward|letter/i.test(i.raw))) out.add('item');
  if (q.resources?.persons?.some(p => p.raw && !/questgiver/i.test(p.raw))) out.add('npc');
  return [...out];
};
const rewardText = q => {
  const bits = [];
  if (q.group?.raw === 'MainQuest') return 'Advances the main story';
  if (q.group?.raw === 'Questline') return 'Advances the questline; pay is set by the step';
  if (q.reward?.gold) bits.push('Gold');
  const items = (q.reward?.items ?? []).filter(i => !/^_reward_|gold$/i.test(i));
  if (items.length) bits.push(items.join(', '));
  const pay = [...new Set((q.sheet?.outcomes ?? []).map(o => o.pay).filter(p => p && p !== 'none'))];
  if (pay.length) bits.push('outcome pay: ' + pay.join(', '));
  return bits.length ? bits.join(' · ') : 'See the quest offer';
};
const asQuest = q => ({
  id: q.id,
  name: q.displayName || fallbackNames[q.id] || q.id,
  kind: kindOf(q),
  category: q.group?.raw === 'Questline' ? 'questlines' : (categoryByGroup.get(q.group?.raw) || 'commoners'),
  group: q.group?.label || 'Unknown',
  giver: q.questor || 'The journal names the questor',
  startsBy: q.startsBy || 'NPC',
  questee: q.questee || 'anyone',
  repute: q.repute ?? null,
  requirement: requirementText(q),
  timeLimit: clockText(q),
  where: placeText(q),
  objectives: sheetSteps(q),
  outcomes: sheetOutcomes(q),
  targetFoes: (q.resources?.foes ?? []).map(f => f.kind).filter(Boolean),
  targetItems: (q.resources?.items ?? []).map(i => i.kind).filter(k => k && !['letter', 'gold'].includes(k)),
  targetPeople: (q.resources?.persons ?? []).map(p => p.raw).filter(Boolean).filter(s => !/^(group|factiontype|face|named)\b/i.test(s)).map(s => s.replace(/^[^ ]+\s+/, '')),
  reward: rewardText(q),
  gold: Boolean(q.reward?.gold),
  notes: q.notes ?? [],
  source: q.filename ? `upstream/snapshot-e4f093166/vendor/dfu-quests/Quests/${q.filename}` : null,
  guide: guidePages[q.id] ?? (q.questline ? lineGuides[q.questline.id] ?? null : null),
  patternGuide: kindOf(q) === 'generated' ? patternGuides[categoryByGroup.get(q.group?.raw)] ?? null : null,
  questline: q.questline ?? null,
  mainOrder: q.group?.raw === 'MainQuest' ? mainOrder(q.id) : null,
  lineOrder: q.questline ? (lineOrder.get(q.questline.id) ?? 99) : null,
  tags: tagsOf(q),
  search: [q.displayName, q.group?.label, q.questor, placeText(q), (q.resources?.foes ?? []).map(f => f.kind).join(' '), (q.resources?.items ?? []).map(i => i.kind).join(' '), (q.notes ?? []).join(' ')].filter(Boolean).join(' ').toLowerCase()
});

const quests = full.quests
  .filter(q => q.group?.raw !== 'Demo')
  .map(asQuest)
  .sort((a, b) => {
    const ai = categories.findIndex(c => c.id === a.category), bi = categories.findIndex(c => c.id === b.category);
    return ai - bi || (a.lineOrder ?? 99) - (b.lineOrder ?? 99) || (a.questline?.step ?? 0) - (b.questline?.step ?? 0) || (a.mainOrder ?? 9999) - (b.mainOrder ?? 9999) || a.name.localeCompare(b.name);
  });
const counts = Object.fromEntries(categories.map(c => [c.id, quests.filter(q => q.category === c.id).length]));
const lines = full.questlines.map(l => ({
  id: l.id, group: l.group, tier: l.tier, title: l.title, lead: l.lead, giver: l.giver, opens: l.opens,
  steps: quests.filter(q => q.questline?.id === l.id).map(q => ({ id: q.id, name: q.name, objectives: q.objectives, outcomes: q.outcomes }))
}));
const output = {
  schemaVersion: 1,
  sourceCommit: full.source?.commit ?? 'e4f093166',
  pack: full.source?.pack ?? null,
  note: 'Quest index for the handbook quest browser; generated from the pinned DFU quest pack. Message text is deliberately omitted.',
  counts, categories, lines, quests
};
await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, JSON.stringify(output));
console.log(`Wrote ${quests.length} quests to ${outputPath} (${(JSON.stringify(output).length / 1024).toFixed(1)} KiB)`);
console.log(counts);
